import React, { useState, useEffect } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import api from '../../services/api';
import '../../styles/ProductDetail.css';
import { toast } from 'react-toastify';

const ProductDetail = () => {
  const { id } = useParams();
  const navigate = useNavigate();

  // State Management
  const [product, setProduct] = useState(null);
  const [relatedProducts, setRelatedProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedSize, setSelectedSize] = useState('');
  const [quantity, setQuantity] = useState(1);
  const [activeTab, setActiveTab] = useState('description');
  const [mainImage, setMainImage] = useState('');

  // Data Fetching
  useEffect(() => {
    const fetchProductData = async () => {
      try {
        setLoading(true);
        const response = await api.get(`/products/${id}`);
        const productData = response.data;
        setProduct(productData);
        setMainImage(productData.imageUrl); // Set initial main image
        setSelectedSize(''); // Reset size selection
        setQuantity(1); // Reset quantity
        setError(null);

        // Fetch related products
        if (productData.categoryId) {
          const relatedResponse = await api.get(`/products/related/${productData.id}`);
          setRelatedProducts(relatedResponse.data);
        }
      } catch (err) {
        console.error('Error fetching product data:', err);
        setError('Failed to load product details. Please try again.');
        toast.error('Failed to load product details.');
      } finally {
        setLoading(false);
      }
    };

    fetchProductData();
    window.scrollTo(0, 0);
  }, [id]); // Refetch when ID changes

  // Helper function to get stock for a given size
  const getStockForSize = (sizeName) => {
    if (!product || !product.sizes) return 0;
    const size = product.sizes.find(s => s.name === sizeName);
    return size ? size.stock : 0;
  };

  // Event Handlers
  const handleSizeSelect = (sizeName) => {
    setSelectedSize(sizeName);
    setQuantity(1); // Reset quantity when size changes
  };

  const handleQuantityChange = (amount) => {
    const stock = getStockForSize(selectedSize);
    setQuantity(prevQuantity => {
      const newQuantity = prevQuantity + amount;
      if (newQuantity < 1) return 1;
      if (newQuantity > stock) {
        toast.warn(`Only ${stock} items available in this size.`);
        return stock;
      }
      return newQuantity;
    });
  };

  const handleAddToCart = () => {
    if (!selectedSize) {
      toast.error('Please select a size first.');
      return;
    }
    // Placeholder for cart logic
    console.log(`Added ${quantity} of ${product.name} (Size: ${selectedSize}) to cart.`);
    toast.success(`${product.name} added to your cart!`);
  };

  const handleCheckoutNow = () => {
    if (!selectedSize) {
      toast.error('Please select a size first.');
      return;
    }
    // Placeholder for checkout logic
    console.log('Proceeding to checkout...');
    toast.info('Redirecting to checkout page...');
    navigate('/checkout');
  };

  // Render Logic
  if (loading) {
    return <div className="loading-spinner"><div></div></div>;
  }

  if (error) {
    return <div className="error-message">{error}</div>;
  }

  if (!product) {
    return <div className="error-message">Product not found.</div>;
  }

  const stockForSelectedSize = getStockForSize(selectedSize);
  const isActionDisabled = !selectedSize || stockForSelectedSize === 0;

  return (
    <div key={id}>
    <div className="product-detail-page" key={id}> {/* `key` ensures component remounts on navigation */}
      <div className="product-detail-container">
        {/* --- Product Gallery --- */}
        <div className="product-gallery">
          <div className="main-image-container">
            <img src={mainImage || product.imageUrl} alt={product.name} className="main-image" />
          </div>
          <div className="thumbnail-container">
            {[product.imageUrl, ...(product.additionalImageUrls || [])].map((url, index) => (
              <img 
                key={index} 
                src={url} 
                alt={`${product.name} thumbnail ${index + 1}`}
                className={`thumbnail-image ${mainImage === url ? 'active' : ''}`}
                onMouseEnter={() => setMainImage(url)}
              />
            ))}
          </div>
        </div>

        {/* --- Product Info --- */}
        <div className="product-info">
          <h1 className="product-name">{product.name}</h1>
          <p className="product-price">${product.price?.toFixed(2)}</p>
          <p className="product-sku">SKU: {product.sku || 'N/A'}</p>

          {/* Size Selector */}
          <div className="size-selector-container">
            <span className="selector-label">Select Size:</span>
            <div className="size-options">
              {product.sizes?.map(size => (
                <button 
                  key={size.id} 
                  className={`size-option ${selectedSize === size.name ? 'active' : ''}`}
                  onClick={() => handleSizeSelect(size.name)}
                  disabled={size.stock === 0}
                  title={size.stock === 0 ? 'Out of Stock' : ''}
                >
                  {size.name}
                </button>
              ))}
            </div>
          </div>

          {/* Availability */}
          <div className="availability-info">
            <span className="selector-label">Availability:</span>
            <span className={`stock-level ${selectedSize && stockForSelectedSize > 0 ? 'in-stock' : 'out-of-stock'}`}>
              {selectedSize 
                ? (stockForSelectedSize > 0 ? `${stockForSelectedSize} In Stock` : 'Out of Stock')
                : 'Select a size'
              }
            </span>
          </div>

          {/* Quantity Selector */}
          <div className="quantity-container">
            <span className="selector-label">Quantity:</span>
            <div className="quantity-selector">
              <button className="quantity-btn" onClick={() => handleQuantityChange(-1)} disabled={isActionDisabled}>-</button>
              <input type="text" className="quantity-input" value={quantity} readOnly />
              <button className="quantity-btn" onClick={() => handleQuantityChange(1)} disabled={isActionDisabled}>+</button>
            </div>
          </div>

          {/* Action Buttons */}
          <div className="action-buttons">
            <button
              className="btn add-to-cart-btn"
              onClick={handleAddToCart}
              disabled={isActionDisabled}
            >
              Add to Cart
            </button>
            <button
              className="btn checkout-now-btn"
              onClick={handleCheckoutNow}
              disabled={isActionDisabled}
            >
              Checkout Now
            </button>
          </div>

          {/* Delivery Info */}
          <div className="delivery-info">
            <p>Free standard shipping on orders over $50.</p>
          </div>
        </div>
      </div>

      {/* --- Product Tabs --- */}
      <div className="product-tabs-section">
        <div className="tab-headers">
          <h3 className={`tab-title ${activeTab === 'description' ? 'active' : ''}`} onClick={() => setActiveTab('description')}>Description</h3>
          <h3 className={`tab-title ${activeTab === 'reviews' ? 'active' : ''}`} onClick={() => setActiveTab('reviews')}>Reviews</h3>
        </div>
        <div className="tab-content">

        {/* Action Buttons */}
        <div className="action-buttons">
          <button
            className="btn add-to-cart-btn"
            onClick={handleAddToCart}
            disabled={isActionDisabled}
          >
            Add to Cart
          </button>
          <button
            className="btn checkout-now-btn"
            onClick={handleCheckoutNow}
            disabled={isActionDisabled}
          >
            Checkout Now
          </button>
        </div>

        {/* Delivery Info */}
        <div className="delivery-info">
          <p>Free standard shipping on orders over $50.</p>
        </div>
      </div>
    </div>

    {/* --- Product Tabs --- */}
    <div className="product-tabs-section">
      <div className="tab-headers">
        <h3 className={`tab-title ${activeTab === 'description' ? 'active' : ''}`} onClick={() => setActiveTab('description')}>Description</h3>
        <h3 className={`tab-title ${activeTab === 'reviews' ? 'active' : ''}`} onClick={() => setActiveTab('reviews')}>Reviews</h3>
      </div>
      <div className="tab-content">
        {activeTab === 'description' && <p>{product.description}</p>}
        {activeTab === 'reviews' && <div className="reviews-placeholder">No reviews yet.</div>}
      </div>
    </div>

    {/* --- Related Products --- */}
    <div className="related-products-container">
      <h2>You May Also Like</h2>
      {relatedProducts.length > 0 ? (
        <div className="related-products-grid">
          {relatedProducts.map((p) => (
            <Link to={`/products/${p.id}`} key={p.id} className="related-product-card">
              <img src={p.imageUrl || '/placeholder.png'} alt={p.name} />
              <h3>{p.name}</h3>
              <p>${p.price}</p>
            </Link>
          ))}
        </div>
      ) : (
        <p>No related products found.</p>
      )}
    </div>
  </div>
</div>
);
};

export default ProductDetail;
